export function requiredRoomCapabilities(info,current){
 if(Object.hasOwn(info,'roomSemantics')){try{return validateRoomSemantics(info.roomSemantics,info.compatibility);}catch{throw new ServiceError('INCOMPATIBLE_GAME');}}
 return current??['core.seed'];
}
export function seedDescription(config){if(!config)return '';const policy=config.seedPolicy??'shared-fixed';return policy==='individual-random'?'Separate random worlds · inspect each actual seed':(policy==='shared-random'?'Shared random seed ':'Fixed shared seed ')+config.seed+' · Randomize loot '+(config.seedPolicy!==undefined&&config.randomizeLoot?'on':'off');}
export function seedDraft(info,data,current){
 const capabilities=info.compatibility.capabilities??[],required=requiredRoomCapabilities(info,current?.requiredCapabilities);
 if(!capabilities.includes('core.seed-policy.v1'))return {seed:Number(data.seed),mode:current?.mode??data.mode,requiredCapabilities:required};
 const seedPolicy=data.seedPolicy??current?.seedPolicy??'shared-random',randomizeLoot=seedPolicy!=='individual-random'&&!!data.randomizeLoot;
 if(randomizeLoot&&!capabilities.includes('core.randomize-loot.v1'))throw new ServiceError('INCOMPATIBLE_GAME');
 return {seed:seedPolicy==='individual-random'?0:Number(data.seed),seedPolicy,randomizeLoot,mode:current?.mode??data.mode,requiredCapabilities:[...new Set([...required.filter(c=>!['core.seed-policy.v1','core.randomize-loot.v1'].includes(c)),'core.seed-policy.v1',...(randomizeLoot?['core.randomize-loot.v1']:[])])]};
}
export function goldSettings(info,data,settings=[]){
 if(!(info.compatibility.capabilities??[]).includes('core.gold')||!(info.compatibility.settingKeys??[]).includes('NT_send_gold'))return settings;
 return [...settings.filter(s=>s.key!=='NT_send_gold'),{key:'NT_send_gold',value:data.sendGold?'true':'false'}];
}
export function bankSettings(info,data,settings=[]){let result=goldSettings(info,data,settings);if(!(info.compatibility.capabilities??[]).includes('core.items'))return result;for(const [field,key]of [['sendWands','NT_send_wands'],['sendFlasks','NT_send_flasks'],['sendItems','NT_send_items']])if((info.compatibility.settingKeys??[]).includes(key))result=[...result.filter(s=>s.key!==key),{key,value:data[field]?'true':'false'}];return result;}
export function testingModeAvailable(info){return info?.developmentFeatures?.testingStartingLoadout?.available===true&&info.developmentFeatures.testingStartingLoadout.settingKey==='NT_testing_mode'&&(info.compatibility?.settingKeys??[]).includes('NT_testing_mode');}
