function settingsKey(value){return JSON.stringify(value,(_k,v)=>v&&typeof v==='object'&&!Array.isArray(v)?Object.fromEntries(Object.keys(v).sort().map(k=>[k,v[k]])):v);}
function settingsDraftKey(id,raw){const v={...raw};if(id==='configure')v.seed=Number(v.seed);if(id==='policy')v.capacity=Number(v.capacity);if(id==='access')v.accounts=v.accounts.split(/[\s,]+/).filter(Boolean).sort().join(' ');if(id==='c1-rules')v.NT_sync_orb_count=v.NT_sync_orbs?Number(v.NT_sync_orb_count):0;return settingsKey(v);}
function settingsError(message,code='INVALID_MESSAGE'){const e=new ServiceError(code);e.settingsMessage=message;return e;}
function numberDraft(v,min,max,label){if(!/^\d+$/.test(String(v))||!Number.isSafeInteger(Number(v))||Number(v)<min||Number(v)>max)throw settingsError(label+' is outside its allowed range.');return Number(v);}
function bytesDraft(v,max,label){if(new TextEncoder().encode(v).length>max)throw settingsError(label+' is too long.');}
function configKey(config){return settingsKey({...config,settings:[...(config.settings??[])].sort((a,b)=>a.key<b.key?-1:a.key>b.key?1:0)});}
function policyKey(r){return settingsKey({name:r.name,capacity:r.capacity??32,allowGuests:!!r.allowGuests,joinLocked:!!r.joinLocked});}
function accessKey(v){return settingsKey({visibility:v.visibility,admittedAccountIds:[...(v.admittedAccountIds??[])].sort()});}
function draftAccess(raw){const ids=raw.accounts.split(/[\s,]+/).filter(Boolean);if(ids.length>32||new Set(ids).size!==ids.length||ids.some(id=>!/^[-a-f0-9]{36}$/i.test(id)||!/^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$/i.test(id)))throw settingsError('Invitations must be distinct account UUIDs (up to 32).');return {visibility:raw.visibility,admittedAccountIds:ids};}
function settingsPlan(){if(!host())throw settingsError('Only the lobby host can save settings.','FORBIDDEN');const plans=[];
 for(const id of settingsOrder){if(room.config.mode==='race'&&['c1-rules','c2-rules'].includes(id))continue;const baseline=settingsBaselines.get(id);if(!baseline)continue;const raw=readSettingsForm(id),changed=settingsDraftKey(id,raw)!==settingsDraftKey(id,baseline);let payload,key,source=formBindings.get(id)??room;
  if(id==='configure'){numberDraft(raw.seed,0,0xffffffff,'Shared seed');if(!(client.info.compatibility.modes??[]).includes(raw.mode)||!['shared-random','shared-fixed','individual-random'].includes(raw.seedPolicy))throw settingsError('Choose a supported mode and seed policy.');for(const [k,v]of Object.entries(raw))if(k.startsWith('setting-'))bytesDraft(v,1024,'Additional setting');const settings=Object.entries(raw).filter(([k,v])=>k.startsWith('setting-')&&v!=='').map(([k,value])=>({key:k.slice(8),value}));payload={configure:{...seedDraft(client.info,raw,source.config),settings:testingModeSettings(client.info,raw,bankSettings(client.info,raw,settings))}};payload.configure=applyRaceDraft(payload.configure,raw.raceDraft,raceCatalogue);key='configure:'+room.roomId;if(changed&&client.authentication&&!client.account?.entitlements?.testingMode&&payload.configure.settings.some(s=>s.key==='NT_testing_mode'&&s.value==='true'))throw settingsError('Your current role cannot save Testing mode.','FORBIDDEN');if(changed&&!configurationAvailable())throw settingsError('World and Transfers require End run or Cancel preparation first.','INVALID_STATE');}
  if(id==='policy'){numberDraft(raw.capacity,Math.max(1,room.members?.length??0),Math.max(room.capacity??32,client.account?.entitlements?.capacityLimit??32),'Capacity');bytesDraft(raw.password,128,'Password');if(!raw.name.trim())throw settingsError('Lobby name is required.');bytesDraft(raw.name,80,'Lobby name');if(changed&&!['waiting','ended','staging'].includes(room.state))throw settingsError('Admission changes require a waiting lobby.','INVALID_STATE');if(changed&&client.authentication&&!client.account?.entitlements?.customLobbyName&&raw.name!==source.name)throw settingsError('Your current role cannot change the lobby name.','FORBIDDEN');const p={capacity:Number(raw.capacity),allowGuests:raw.allowGuests,joinLocked:raw.joinLocked};if(client.authentication)p.name=client.account?.entitlements?.customLobbyName?raw.name:source.name;if(raw.clearPassword)p.password='';else if(raw.password)p.password=raw.password;payload={roomPolicy:p};key='roomPolicy:'+room.roomId;}
  if(id==='statistics-policy'){payload={roomPolicy:{publicStats:!!raw.publicStats}};key='roomPolicy:'+room.roomId;}
  if(id==='access'){if(!['public','private'].includes(raw.visibility))throw settingsError('Choose Public or Private visibility.');payload={roomAccess:draftAccess(raw)};if(changed&&!accessKnown)throw settingsError('Reload the complete invitation list before saving.','FORBIDDEN');key='roomAccess:'+room.roomId;}
  if(id==='c1-rules'){if(!c1Snapshot||c1RoomId!==room.roomId)throw settingsError('Reload player rules before saving.');const rules={};for(const k of Object.keys(c1Snapshot.rules))rules[k]=k==='NT_sync_orb_count'?numberDraft(raw[k],0,0xffffffff,'Orb limit'):raw[k];if(!['end','weak_respawn','full_respawn'].includes(rules.NT_death_penalty))throw settingsError('Choose a supported death mode.');if(!rules.NT_sync_orbs)rules.NT_sync_orb_count=0;payload={roomId:room.roomId,rulesSet:{expectedRevision:c1Snapshot.revision,rules}};source=structuredClone(c1Snapshot);key='c1:'+room.roomId;}
  if(id==='c2-rules'){if(!c2Snapshot||c2RoomId!==room.roomId)throw settingsError('Reload world rules before saving.');payload={roomId:room.roomId,rulesSet:{expectedRevision:c2Snapshot.revision,rules:{NT_sync_steve:raw.NT_sync_steve}}};source=structuredClone(c2Snapshot);key='c2:'+room.roomId;}
  if(changed)plans.push({id,raw,baseline:structuredClone(baseline),source:structuredClone(source),payload,key,label:settingsNames[id]});
 }return plans;
}
async function settingsCurrent(plans,binding){const value=await client.rpc({roomGet:{}},room);if(!validAccess(binding))throw new ServiceError('STALE_EPOCH');if(!value.room)throw new ServiceError('NOT_FOUND');const current=value.room;
 for(const p of plans){if(p.id==='statistics-policy'&&!!current.publicStats!==!!p.source.publicStats)throw settingsError('Statistics/privacy changed elsewhere. Reload settings before saving.','STALE_REVISION');if(p.id==='configure'&&configKey(current.config)!==configKey(p.source.config))throw settingsError('World settings changed elsewhere. Reload settings before saving.','STALE_REVISION');if(p.id==='policy'&&(policyKey(current)!==policyKey(p.source)||Object.hasOwn(p.payload.roomPolicy,'password')&&current.revision!==p.source.revision))throw settingsError('Admission changed elsewhere. Reload settings before saving.','STALE_REVISION');if(p.id==='access'&&(!value.access||accessKey(value.access)!==accessKey(draftAccess(p.baseline))))throw settingsError('Access changed elsewhere. Reload settings before saving.','STALE_REVISION');
  if(p.id==='c1-rules'||p.id==='c2-rules'){const lane=p.id==='c1-rules'?'c1':'c2',live=await client[lane]({roomId:room.roomId,rulesGet:{}});if(!validAccess(binding))throw new ServiceError('STALE_EPOCH');const snapshot=lane==='c1'?live.snapshot:live.snapshot.rules;if(settingsKey(snapshot.rules)!==settingsKey(p.source.rules))throw settingsError(p.label+' changed elsewhere. Reload settings before saving.','CONFLICT');p.payload.rulesSet.expectedRevision=snapshot.revision;}
 }return value;
}
function committedSettings(p,response,apply=true){let baseline={...p.raw};if(response.room){room=response.room;formBindings.set(p.id,structuredClone(room));if(p.id==='configure'){const c=room.config;Object.assign(baseline,{seed:String(c.seed),seedPolicy:c.seedPolicy??'shared-fixed',randomizeLoot:!!c.randomizeLoot,mode:c.mode,testingMode:(c.settings??[]).some(s=>s.key==='NT_testing_mode'&&s.value==='true')});for(const [name,key]of [['sendGold','NT_send_gold'],['sendWands','NT_send_wands'],['sendFlasks','NT_send_flasks'],['sendItems','NT_send_items']])baseline[name]=(c.settings??[]).find(s=>s.key===key)?.value!=='false';reports.clear();}if(p.id==='statistics-policy')baseline={publicStats:!!room.publicStats};if(p.id==='policy')Object.assign(baseline,{name:room.name,capacity:String(room.capacity??32),allowGuests:!!room.allowGuests,joinLocked:!!room.joinLocked,password:'',clearPassword:false});}
 if(p.id==='access'&&response.access){accessKnown=true;accessBinding=accessScope();baseline={visibility:response.access.visibility,accounts:(response.access.admittedAccountIds??[]).join('\n')};}
 if(p.id==='c1-rules'){c1Snapshot=response.snapshot;c1RoomId=room.roomId;baseline=Object.fromEntries(Object.entries(c1Snapshot.rules).map(([k,v])=>[k,typeof v==='boolean'?v:String(v)]));}
 if(p.id==='c2-rules'){c2Snapshot=response.snapshot.rules;c2RoomId=room.roomId;baseline={NT_sync_steve:c2Snapshot.rules.NT_sync_steve};}
 if(apply)for(const [k,v]of Object.entries(baseline)){const field=$(p.id).elements[k];if(field&&settingsKey(field.type==='checkbox'?!!field.checked:String(field.value))===settingsKey(p.raw[k])){if(field.type==='checkbox')field.checked=v;else field.value=v;}}
 settingsBaselines.set(p.id,baseline);if(settingsDraftKey(p.id,readSettingsForm(p.id))===settingsDraftKey(p.id,baseline))dirtyForms.delete(p.id);else dirtyForms.add(p.id);renderRoom();
}
async function saveSettings(){if(settingsSaving||settingsUnknown)throw settingsError('Check the original unconfirmed change before saving again.','MUTATION_UNCERTAIN');settingsSaving=true;const saved=[];let currentPlan=null;try{const plans=settingsPlan();if(!plans.length){$('settings-outcome').textContent='No settings changed.';return;}const other=[...(client.pendingMutations?.entries()??[])].find(([,p])=>p.request.roomId===room.roomId&&(p.lane||p.request.configure||p.request.roomPolicy||p.request.roomAccess));if(other)throw settingsError('Check the original unconfirmed change before saving again.','MUTATION_UNCERTAIN');const binding=accessScope();let current=await settingsCurrent(plans,binding);room=current.room;
  for(const p of plans){currentPlan=p;if(!validAccess(binding))throw new ServiceError('STALE_EPOCH');let response;if(p.id==='c1-rules'||p.id==='c2-rules')response=await client[p.id==='c1-rules'?'c1':'c2'](p.payload);else{current=await settingsCurrent([p],binding);room=current.room;response=await mutate(p.payload,current.room);}if(!validAccess(binding))throw new ServiceError('STALE_EPOCH');committedSettings(p,response);saved.push(p.label);}
  $('settings-outcome').textContent='Settings saved: '+saved.join(', ')+'.';
 }catch(e){if(currentPlan&&client.pendingMutations?.has(currentPlan.key))settingsUnknown={key:currentPlan.key,plan:currentPlan};$('settings-outcome').textContent=(saved.length?'Saved '+saved.join(', ')+'. ':'No changes confirmed. ')+(settingsUnknown?'The '+currentPlan.label+' outcome is unconfirmed. Check the original change; remaining drafts are kept.':(e.settingsMessage??messages[e.code]??'Save failed.')+' Remaining drafts are kept.');throw e;}finally{settingsSaving=false;}}
async function reloadSettings(){if(dirtyForms.size&&!window.confirm('Reload all current settings and replace unsaved edits? Unconfirmed original requests will still be retained.'))return;const binding=accessScope(),value=await client.rpc({roomGet:{}},room);if(!validAccess(binding))throw new ServiceError('STALE_EPOCH');const live1=c1Snapshot?await client.c1({roomId:room.roomId,rulesGet:{}}):null,live2=c2Snapshot?await client.c2({roomId:room.roomId,rulesGet:{}}):null;if(!validAccess(binding))throw new ServiceError('STALE_EPOCH');room=value.room;dirtyForms.clear();if(live1)committedSettings({id:'c1-rules',raw:readSettingsForm('c1-rules')},live1);if(live2)committedSettings({id:'c2-rules',raw:readSettingsForm('c2-rules')},live2);applyAccess(value.access,true);renderRoom(true);$('settings-outcome').textContent=settingsUnknown?'Current settings loaded. The original change remains unconfirmed; check it before saving.':'Current settings loaded.';}
for(const id of ['configure','policy','access','c1-rules','c2-rules'])$(id).addEventListener('submit',event=>{event.preventDefault();if(busy||settingsSaving)return;return action(saveSettings);});
$('save-settings').addEventListener('click',()=>{if(busy||settingsSaving)return;return action(saveSettings);});$('reload-settings').addEventListener('click',()=>{if(busy||settingsSaving)return;return action(reloadSettings);});
$('c1-rules').elements.NT_sync_orbs.addEventListener('change',c1Buttons);
bind('moderate',async data=>{room=(await mutate({roomModerate:data},room)).room;renderRoom();notice('Moderation applied.');});
async function sendChatDraft(data,target){if(!validAccess(target.binding))throw new ServiceError('STALE_EPOCH');if(!data.text?.trim()||chatBytes(data.text)>1024)throw new ServiceError('INVALID_MESSAGE');chatView.feedback('Sending…');try{const result=client.sendRoomChat?await client.sendRoomChat(data.text,target.room):await client.rpc({chatSend:data},target.room);if(!validAccess(target.binding))return;chatView.append(result);const field=$('chat').elements.text;if(field.value===data.text&&!field.composing)field.value='';chatView.hideSuggestions();chatView.feedback('Sent.');await chat();}catch(e){if(validAccess(target.binding))chatView.feedback(e.code==='CAPACITY'?'Rate limit reached. Your draft is kept; wait before retrying.':(e.code==='EXPIRED'||e.code==='RECEIPT_EXPIRED')?'Receipt expired; delivery is unknown. Review the expired message before sending again. Your draft is kept.':e.code==='CHAT_MUTED'?'Room chat is muted. Your draft is kept; you can still read and play.':e.verifiedResponse?'Message refused. Your draft is kept.':'Send not confirmed. Retry the same message; your draft is kept.');throw e;}}
bind('chat',sendChatDraft,()=>({binding:accessScope(),room}));
$('chat-retry').addEventListener('click',()=>action(async()=>{const pending=client.pendingChat;if(pending?.roomId!==room?.roomId||pending.generation!==client.generation)throw new ServiceError('STALE_EPOCH');if(pending.expired){await reviewExpiredOutcome('chat',pending);return;}await sendChatDraft({text:pending.text},{binding:accessScope(),room});}));
$('chat').elements.text.addEventListener('compositionstart',()=>{$('chat').elements.text.composing=true;});
$('chat').elements.text.addEventListener('compositionend',()=>{$('chat').elements.text.composing=false;});
bind('preview',async data=>open(data.roomId.trim()));
$('lobby-search').addEventListener('input',()=>{filter=$('lobby-search').value.trim().toLocaleLowerCase();if(viewOnly&&!signedIn())renderPublicDiscovery();else renderDiscovery();});
function closePlayer(){const visible=!$('player-dialog').hidden;$('player-dialog').hidden=true;detailsTarget=null;$('player-actions').replaceChildren();if(visible)detailsFocus?.focus?.();detailsFocus=null;}
async function openPlayer(accountId,desktopId,focus){const binding=accessScope(),target=room,result=await client.rpc({roomPlayerDetails:{accountId,...(desktopId?{desktopId}:{})}},target);if(!validAccess(binding))return;const details=result.playerDetails;if(!details)throw new ServiceError('NOT_FOUND');detailsTarget={...details,roomId:target.roomId,revision:details.roomRevision,actorRole:client.account?.role};detailsFocus=focus;$('player-title').textContent=details.principal?.displayName??'Player';$('player-identity').textContent=[details.principal?.source,details.role,details.chatMuted?'Room chat muted':'Room chat available'].join(' · ');const member=target.members?.find(m=>m.desktopId===desktopId);$('player-state').textContent=[playerRows.get(desktopId)?.model?.cells.status.label??(details.banned?'Banned from this lobby':'Current player'),member?.included===false?'Excluded':'Included'].filter(Boolean).join(' · ');const report=reports.get(desktopId);detailsTarget.contentDigest=report?.contentDigest;detailsTarget.observationRevision=report?.observationRevision;$('player-inspection').textContent=report?'Actual seed: '+(report.seedStatus==='known'?report.actualSeed:'unknown')+'\nOrdered active mods:\n'+(report.activeMods??[]).join('\n'):'Awaiting inspection — no actual seed or ordered mods reported yet.';$('player-diagnostics').textContent='Account '+accountId+(desktopId?' · Desktop '+desktopId:'')+(member?.readinessReason?'\nReadiness reason: '+member.readinessReason:'')+(playerRows.get(desktopId)?.model?.failure?'\n'+playerRows.get(desktopId).model.failure:'')+(report?'\nObserved NT2 mod: '+(report.modVersion??'not reported')+'\nRequired NT2 mod: '+(client.info.compatibility?.modVersion??'unknown')+'\nObserved native runtime: '+(report.bridgeVersion??'not reported')+'\nRequired native runtime: '+(client.info.compatibility?.bridgeVersion??'unknown')+'\nCaptured: '+report.capturedAt+'\nCollector: '+(report.collectorFailure||'no failure reported'):'');$('player-actions').replaceChildren();for(const actionName of details.actions??[]){const button=document.createElement('button');button.type='button';button.className=['kick','ban'].includes(actionName)?'danger':'subtle';button.textContent=({kick:'Kick player',ban:'Ban from lobby',mute:'Mute room chat',unmute:'Unmute room chat',unban:'Remove room ban'})[actionName];button.addEventListener('click',()=>action(()=>moderatePlayer(details,actionName,binding,target)));$('player-actions').append(button);}$('player-dialog').hidden=false;$('player-close').focus?.();}
async function refreshPlayerDialog(){if(!detailsTarget)return;const captured=detailsTarget,binding=accessScope();try{const value=(await client.rpc({roomPlayerDetails:{accountId:captured.accountId,...(captured.desktopId?{desktopId:captured.desktopId}:{})}},room)).playerDetails;if(detailsTarget!==captured||!validAccess(binding))return;if(!value||value.role!==captured.role||value.chatMuted!==captured.chatMuted||JSON.stringify(value.actions)!==JSON.stringify(captured.actions)){closePlayer();notice('Player details or permissions changed. Open the player again to review.');}}catch(e){if(detailsTarget===captured)closePlayer();if(!['FORBIDDEN','NOT_FOUND'].includes(e.code))throw e;}}
async function moderatePlayer(details,actionName,binding,target){if(!validAccess(binding))throw new ServiceError('STALE_EPOCH');const current=(await client.rpc({roomPlayerDetails:{accountId:details.accountId,...(details.desktopId?{desktopId:details.desktopId}:{})}},target)).playerDetails;if(!validAccess(binding))return;if(!current?.actions?.includes(actionName))throw new ServiceError('FORBIDDEN');const explanation=actionName==='mute'?'This prevents sending room chat in this lobby only. Reading chat and playing stay available.':actionName==='kick'?'They may rejoin under normal admission.':actionName==='ban'?'They cannot rejoin this lobby until the room ban is removed.':'';if(!window.confirm(actionName+' '+current.principal.displayName+' in “'+target.name+'”? '+explanation))return;const result=await mutate({roomModerate:{accountId:current.accountId,action:actionName,...(current.desktopId?{desktopId:current.desktopId}:{})}},{...target,revision:current.roomRevision});if(!validAccess(binding))return;room=result.room;closePlayer();renderRoom();notice('Player moderation saved.');}
async function loadBans(append=false){const binding=accessScope(),target=room,result=await client.rpc({roomBanList:{limit:32,afterAccountId:append?banCursor:''}},target);if(!validAccess(binding))return;if(!append)$('bans').replaceChildren();for(const entry of result.roomBans??[]){const li=document.createElement('li'),name=document.createElement('span');name.textContent=entry.principal?.displayName??'Player';li.append(name);if(entry.actions?.includes('unban')){const button=document.createElement('button');button.textContent='Remove ban';button.addEventListener('click',()=>action(async()=>{await moderatePlayer(entry,'unban',binding,target);if(validAccess(binding))await loadBans();}));li.append(button);}$('bans').append(li);}banCursor=result.nextRoomBanAccountId??'';$('more-bans').hidden=!banCursor;}
async function reviewExpiredOutcome(key,pending){
 const generation=client.generation,credentials=client.credentials,service=client.info.serviceId,epoch=client.info.serviceEpoch;
 const current=()=>generation===client.generation&&credentials===client.credentials&&service===client.info.serviceId&&epoch===client.info.serviceEpoch;
 // Read current state, never resend the expired operation. A visible snapshot
 // cannot prove whether an old operation committed (chat history is bounded).
 let reviewed;if(pending.request.roomCreate)await discover();else{await sync();if(key==='chat')await chat();if(room)reviewed=pending.lane?await client[pending.lane]({roomId:room.roomId,rulesGet:{}}):await client.rpc({roomGet:{}},room);}
 if(!current())throw new ServiceError('STALE_EPOCH');
 const description=pending.lane?'live settings change':key==='chat'?'message “'+pending.text+'”':'lobby change '+Object.keys(pending.request).filter(k=>['roomCreate','configure','roomPolicy','roomAccess','roomModerate','cancelRun','endRun','roomDelete'].includes(k)).join('');
 const snapshot=pending.request.roomCreate?'Visible lobbies: '+[...roomSummaries.values()].map(r=>r.name+' ('+r.state+')').join(', '):room?'Lobby “'+room.name+'” · '+room.state+' · capacity '+room.capacity+' · joins '+(room.joinLocked?'locked':'open')+' · '+room.visibility+'\nConfiguration: '+JSON.stringify(room.config)+'\nPlayers: '+(room.members??[]).map(m=>(m.principal?.displayName??'Player')+(m.chatMuted?' (chat muted)':'')).join(', '):'Lobby is no longer available to this account.';
 if(!window.confirm(snapshot+(pending.lane?'\nCurrent live rules: '+JSON.stringify(reviewed?.snapshot):'')+'\n\nCurrent '+(pending.request.roomCreate?'lobby list':'lobby state')+' has been refreshed. Review it before continuing. The receipt for '+description+' is no longer confirmable; the earlier action may already have succeeded. Visible lists and chat history may be incomplete. A new action could repeat it. Acknowledge this unknown outcome and allow a deliberate new action? Nothing will be resent.'))return;
 if(!current())throw new ServiceError('STALE_EPOCH');
 client.acknowledgeExpiredOutcome(key,pending);
 if(settingsUnknown?.key===key){const plan=settingsUnknown.plan;settingsUnknown=null;if(room&&reviewed)committedSettings(plan,reviewed,false);$('settings-outcome').textContent='Unknown outcome acknowledged against current state. Unsaved drafts are kept; Save settings to continue.';}else if(key!=='chat'&&room){renderRoom(true);dirtyForms.clear();}
 if(key==='chat')chatView.feedback('Unknown earlier delivery acknowledged. Your draft is kept. Review the history before deliberately sending; it could repeat the earlier message.');
 notice('Unknown earlier outcome acknowledged. Nothing was resent. Review current values before deliberately making a new action.');
}
function pendingChange(){return [...(client.pendingMutations?.entries()??[])].find(([,p])=>p.generation===client.generation&&(p.request.roomCreate||p.request.roomId===room?.roomId));}
$('retry-change').addEventListener('click',()=>action(async()=>{const pending=pendingChange();if(!pending)throw new ServiceError('NOT_FOUND');if(pending[1].expired||pending[1].requiresReview){await reviewExpiredOutcome(...pending);return;}const generation=client.generation,page=pollGeneration,result=await client.retryRoomMutation(pending[0]);if(generation!==client.generation||page!==pollGeneration)return;if(settingsUnknown?.key===pending[0]){const plan=settingsUnknown.plan;settingsUnknown=null;committedSettings(plan,result);$('settings-outcome').textContent='Previous '+plan.label+' confirmed. Remaining drafts are kept; Save settings to continue.';return;}if(result.room){if(pending[1].request.roomCreate)selectRoom(result.room,result.access?.visibility,result.access);else if(result.room.roomId===room?.roomId){room=result.room;applyAccess(result.access);renderRoom();}}if(result.deletedRoomId===room?.roomId)clearRoom();notice('Previous change confirmed. Refresh settings to review the current values.');}));
