for(const [id,payload] of [['cancel',{cancelRun:{}}],['end',{endRun:{}}]])$(id).addEventListener('click',()=>action(async()=>{room=(await mutate(payload,room)).room;renderRoom();notice(id==='cancel'?'Preparation cancelled. Any generated world requires restart.':'Run ended.');}));
$('delete-room').addEventListener('click',()=>action(async()=>{
 if(!host())throw new ServiceError('FORBIDDEN');
 if(!['waiting','ended'].includes(room.state)){notice('End the run or cancel preparation before deleting this lobby.',true);return;}
 const target=room;if(!window.confirm('Delete lobby “'+target.name+'”? It will disappear from the lobby list. Its gameplay statistics will no longer be available.'))return;
 try{const result=await mutate({roomDelete:{}},target);if(result.deletedRoomId!==target.roomId)throw new ServiceError('STALE_EPOCH');clearRoom();await discover();notice('Lobby deleted.');}
 catch(e){if(e.code==='INVALID_STATE'){notice('End the run or cancel active preparation before deleting this lobby.',true);return;}throw e;}
}));
